/**
 * Context helpers for request handling
 */

import type { RouteContext } from './types.js';
import { PayloadTooLargeError } from './errors.js';

const BODY_CANCEL_DEADLINE_MS = 50;

async function cancelBodyWithDeadline(body: ReadableStream<Uint8Array> | null): Promise<void> {
  if (!body || body.locked) return;
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    await Promise.race([
      body.cancel('PAYLOAD_TOO_LARGE').catch(() => undefined),
      new Promise<void>((resolve) => {
        timer = setTimeout(resolve, BODY_CANCEL_DEADLINE_MS);
      }),
    ]);
  } finally {
    if (timer !== undefined) clearTimeout(timer);
  }
}

async function cancelReaderWithDeadline(reader: ReadableStreamDefaultReader<Uint8Array>): Promise<void> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    await Promise.race([
      reader.cancel('PAYLOAD_TOO_LARGE').catch(() => undefined),
      new Promise<void>((resolve) => {
        timer = setTimeout(resolve, BODY_CANCEL_DEADLINE_MS);
      }),
    ]);
  } finally {
    if (timer !== undefined) clearTimeout(timer);
  }
}

/**
 * Read a request body fully while enforcing a maximum byte length.
 *
 * Rejects early via the Content-Length header when present, and otherwise
 * streams the body and aborts as soon as the accumulated size exceeds the
 * limit — so an attacker cannot exhaust memory by omitting Content-Length.
 */
async function readBodyBufferWithLimit(
  request: Request,
  maxBodyBytes: number
): Promise<Uint8Array> {
  const contentLength = request.headers.get('content-length');
  if (contentLength !== null) {
    const declared = Number(contentLength);
    if (Number.isFinite(declared) && declared > maxBodyBytes) {
      await cancelBodyWithDeadline(request.body);
      throw new PayloadTooLargeError(
        `Request body exceeds the maximum allowed size of ${maxBodyBytes} bytes`,
        'PAYLOAD_TOO_LARGE'
      );
    }
  }

  const body = request.body;
  // No stream available (e.g. an already-buffered mock): fall back to
  // arrayBuffer() so multipart and other binary payloads are not corrupted.
  if (!body) {
    const bytes = new Uint8Array(await request.arrayBuffer());
    if (bytes.byteLength > maxBodyBytes) {
      throw new PayloadTooLargeError(
        `Request body exceeds the maximum allowed size of ${maxBodyBytes} bytes`,
        'PAYLOAD_TOO_LARGE'
      );
    }
    return bytes;
  }

  const reader = body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        total += value.byteLength;
        if (total > maxBodyBytes) {
          // Await ordinary producer cancellation, but cap the wait because a
          // tee'd stream coordinates cancellation with every branch.
          await cancelReaderWithDeadline(reader);
          throw new PayloadTooLargeError(
            `Request body exceeds the maximum allowed size of ${maxBodyBytes} bytes`,
            'PAYLOAD_TOO_LARGE'
          );
        }
        chunks.push(value);
      }
    }
  } finally {
    reader.releaseLock();
  }

  return concatChunks(chunks, total);
}

function concatChunks(chunks: Uint8Array[], total: number): Uint8Array {
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return out;
}

/**
 * Create a RouteContext from a Request and path params
 */
export function createRouteContext(
  request: Request,
  params: Record<string, string>,
  options?: { maxBodyBytes?: number }
): RouteContext {
  const url = new URL(request.url);
  const query = url.searchParams;
  const maxBodyBytes = options?.maxBodyBytes;

  // Cache for parsed bodies to avoid multiple parsing
  let jsonCache: Promise<any> | null = null;
  let textCache: Promise<string> | null = null;
  let formDataCache: Promise<FormData> | null = null;
  let bodyBufferCache: Promise<Uint8Array> | null = null;

  // When a limit is configured, buffer the body once (with enforcement) and
  // derive json/text/formData from that single read. Otherwise defer to the
  // native Request parsers.
  const readBuffer = (): Promise<Uint8Array> => {
    if (!bodyBufferCache) {
      bodyBufferCache = readBodyBufferWithLimit(request, maxBodyBytes!);
    }
    return bodyBufferCache;
  };

  const readText = (): Promise<string> => {
    if (!textCache) {
      textCache =
        maxBodyBytes !== undefined
          ? readBuffer().then((bytes) => new TextDecoder().decode(bytes))
          : request.text();
    }
    return textCache;
  };

  return {
    params,
    query,
    url,

    json: async <T = any>(): Promise<T> => {
      if (!jsonCache) {
        jsonCache =
          maxBodyBytes !== undefined
            ? readText().then((text) => JSON.parse(text))
            : request.json();
      }
      return jsonCache as Promise<T>;
    },

    text: async (): Promise<string> => {
      return readText();
    },

    formData: async (): Promise<FormData> => {
      if (!formDataCache) {
        if (maxBodyBytes !== undefined) {
          formDataCache = readBuffer().then((bytes) => {
            // Parse from the same bounded binary buffer used by json() and
            // text(). Response.formData() preserves multipart file bytes.
            return new Response(bytes.buffer as ArrayBuffer, { headers: request.headers }).formData();
          });
        } else {
          formDataCache = request.formData();
        }
      }
      return formDataCache;
    },
  };
}

/**
 * Merge user context with route context
 */
export function mergeContexts<TContext>(
  userContext: TContext,
  routeContext: RouteContext
): TContext & RouteContext {
  return {
    ...userContext,
    ...routeContext,
  };
}
/**
 * PHASE_02 role tests: TV-ROLE-UPSERT-001, TV-ROLE-LIST-001, TV-ROLE-DENY-001, TV-ENV-ERR-001.
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { createCmsfnServer } from "../index.js";
import type { CmsfnServerConfig } from "../index.js";
import { memoryAdapter } from "@superfunctions/db/adapters";
import type { CmsfnRole } from "cmsfn";

const CONTENTFN_BASE = "http://contentfn.test";

function contentfnUpResponse() {
  return {
    ok: true,
    result: {
      serverTime: new Date().toISOString(),
      capabilities: [
        "content.schema",
        "content.docs",
        "content.assets",
        "content.webhooks",
        "content.realtime",
      ],
      limits: { maxPayloadBytes: 1e6, maxPatchOps: 100 },
    },
  };
}

function minimalConfig(overrides: Partial<CmsfnServerConfig> = {}): CmsfnServerConfig {
  return {
    contentfn: { baseUrl: CONTENTFN_BASE },
    datasets: [{ name: "prod" }, { name: "staging" }],
    desk: { kind: "divider" },
    auth: { kind: "custom" },
    db: memoryAdapter(),
    ...overrides,
  };
}

function listen(server: ReturnType<typeof createCmsfnServer>): Promise<{ port: number; close: () => void }> {
  return new Promise((resolve) => {
    server.listen(0, () => {
      const addr = server.address();
      const port = typeof addr === "object" && addr !== null ? addr.port : 0;
      resolve({
        port,
        close: () => server.close(),
      });
    });
  });
}

/** Only mock fetch for ContentFn URL so status and other requests work. */
function installContentfnFetchMock(
  contentfnBehavior: (url: string) => Promise<Response>
) {
  const realFetch = globalThis.fetch;
  vi.stubGlobal(
    "fetch",
    (input: string | URL | Request, init?: RequestInit) => {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : (input as Request).url;
      if (url.startsWith(CONTENTFN_BASE)) {
        return contentfnBehavior(url);
      }
      return realFetch(input as string, init);
    }
  );
}

describe("PHASE_02: Roles CRUD + enforcement", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  describe("TV-ROLE-UPSERT-001: upsert role", () => {
    it("POST /cmsfn/roles/upsert with valid role returns ok and role", async () => {
      installContentfnFetchMock(async () =>
        new Response(JSON.stringify(contentfnUpResponse()), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        })
      );

      const server = createCmsfnServer(minimalConfig());
      const { port, close } = await listen(server);
      try {
        const role: CmsfnRole = {
          id: "editor",
          name: "Editor",
          rules: [{ datasets: "*", types: "*", actions: ["doc.read", "doc.patch"] }],
        };
        const res = await fetch(`http://127.0.0.1:${port}/cmsfn/roles/upsert`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ role }),
        });
        const data = await res.json();
        expect(res.status).toBe(200);
        expect(data.ok).toBe(true);
        expect(data.result).toBeDefined();
        expect(data.result.role).toEqual(role);
      } finally {
        close();
      }
    });
  });

  describe("TV-ROLE-LIST-001: list roles", () => {
    it("POST /cmsfn/roles/list returns ok and roles in deterministic order", async () => {
      installContentfnFetchMock(async () =>
        new Response(JSON.stringify(contentfnUpResponse()), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        })
      );

      const server = createCmsfnServer(minimalConfig());
      const { port, close } = await listen(server);
      try {
        // Upsert two roles in one order
        await fetch(`http://127.0.0.1:${port}/cmsfn/roles/upsert`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            role: { id: "b-role", name: "B", rules: [{ datasets: "*", types: "*", actions: ["doc.read"] }] },
          }),
        });
        await fetch(`http://127.0.0.1:${port}/cmsfn/roles/upsert`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            role: { id: "a-role", name: "A", rules: [{ datasets: "*", types: "*", actions: ["doc.read"] }] },
          }),
        });
        const res = await fetch(`http://127.0.0.1:${port}/cmsfn/roles/list`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ dataset: "prod" }),
        });
        const data = await res.json();
        expect(res.status).toBe(200);
        expect(data.ok).toBe(true);
        expect(Array.isArray(data.result.roles)).toBe(true);
        // Deterministic order by id (asc)
        const ids = data.result.roles.map((r: CmsfnRole) => r.id);
        expect(ids).toEqual(["a-role", "b-role"]);
      } finally {
        close();
      }
    });
  });

  describe("TV-ROLE-DENY-001: denied action returns PERMISSION_DENIED", () => {
    it("POST /cmsfn/publish when role denies doc.publish returns PERMISSION_DENIED", async () => {
      installContentfnFetchMock(async () =>
        new Response(JSON.stringify(contentfnUpResponse()), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        })
