/**
 * CmsFn release storage via @superfunctions/db adapter.
 * Table: cmsfn_releases (releaseId, dataset, name, publishAt, docIds, createdAt, updatedAt).
 * List order: createdAt desc, releaseId asc.
 */

import type { Adapter } from "@superfunctions/db";
import type { CmsfnEnvelope, CmsfnRelease } from "cmsfn";
import { ok, err } from "cmsfn";
import { randomUUID } from "node:crypto";
import { MAX_DOCS_PER_RELEASE } from "../limits/limits.js";

export const CMSFN_RELEASES_TABLE = "cmsfn_releases";

export interface ReleasesStorageConfig {
  db: Adapter;
}

interface ReleaseRow {
  releaseId: string;
  dataset: string;
  name: string;
  publishAt: string | null;
  docIds: string[];
  createdAt: string;
  updatedAt: string;
}

function nowIso(): string {
  return new Date().toISOString();
}

/**
 * Create a release. Returns releaseId.
 */
export async function createRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; name: string; publishAt?: string | null }
): Promise<CmsfnEnvelope<{ releaseId: string }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const name = typeof input.name === "string" ? input.name.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!name) return err("VALIDATION_FAILED", "name is required", { path: "name" });
  const publishAt =
    input.publishAt === undefined || input.publishAt === null
      ? null
      : typeof input.publishAt === "string"
        ? input.publishAt.trim() || null
        : null;

  const releaseId = randomUUID();
  const now = nowIso();
  const row: ReleaseRow = {
    releaseId,
    dataset,
    name,
    publishAt,
    docIds: [],
    createdAt: now,
    updatedAt: now,
  };
  await config.db.create({
    model: CMSFN_RELEASES_TABLE,
    data: row,
  });
  return ok({ releaseId });
}

/**
 * List releases for dataset. Order: createdAt desc, releaseId asc.
 */
export async function listReleases(
  config: ReleasesStorageConfig,
  input: { dataset: string }
): Promise<CmsfnEnvelope<{ releases: CmsfnRelease[] }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });

  const rows = await config.db.findMany({
    model: CMSFN_RELEASES_TABLE,
    where: [{ field: "dataset", operator: "eq", value: dataset }],
    orderBy: [
      { field: "createdAt", direction: "desc" },
      { field: "releaseId", direction: "asc" },
    ],
  });
  const releases: CmsfnRelease[] = (rows as ReleaseRow[]).map((r) => ({
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  }));
  return ok({ releases });
}

/**
 * Get one release by dataset and releaseId.
 */
export async function getRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string }
): Promise<CmsfnRelease | null> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  if (!dataset || !releaseId) return null;

  const row = await config.db.findOne({
    model: CMSFN_RELEASES_TABLE,
    where: [{ field: "releaseId", operator: "eq", value: releaseId }],
  });
  if (!row || typeof row !== "object") return null;
  const r = row as ReleaseRow;
  return {
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  };
}

/**
 * Add a doc to a release. Rejects if release not found or docIds would exceed max.
 */
export async function addDocToRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string; docId: string }
): Promise<CmsfnEnvelope<Record<string, never>>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  const docId = typeof input.docId === "string" ? input.docId.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!releaseId) return err("VALIDATION_FAILED", "releaseId is required", { path: "releaseId" });
  if (!docId) return err("VALIDATION_FAILED", "docId is required", { path: "docId" });

  const release = await getRelease(config, { dataset, releaseId });
  if (!release) return err("NOT_FOUND", "Release not found", { releaseId });

  const docIds = [...release.docIds];
  if (docIds.includes(docId)) return ok({});
  if (docIds.length >= MAX_DOCS_PER_RELEASE) {
    return err("VALIDATION_FAILED", "Release has reached max document count", {
      path: "docId",
      limit: MAX_DOCS_PER_RELEASE,
    });
  }
  docIds.push(docId);
  docIds.sort();

  await config.db.update({
    model: CMSFN_RELEASES_TABLE,
    where: [{ field: "releaseId", operator: "eq", value: releaseId }],
    data: { docIds, updatedAt: nowIso() },
  });
  return ok({});
}
/**
 * CmsFn role storage via @superfunctions/db adapter.
 * Table: cmsfn_roles (id, name, rules JSON).
 * Roles are global; list(dataset) returns all roles in deterministic order (by id).
 */

import type { Adapter } from "@superfunctions/db";
import type { CmsfnEnvelope } from "cmsfn";
import type { CmsfnRole } from "cmsfn";
import { ok, err } from "cmsfn";

export const CMSFN_ROLES_TABLE = "cmsfn_roles";

export interface RolesStorageConfig {
  db: Adapter;
}

function validateRoleId(roleId: string): { ok: true; id: string } | { ok: false; message: string } {
  const trimmed = roleId?.trim();
  if (typeof trimmed !== "string" || trimmed.length === 0) {
    return { ok: false, message: "Invalid roleId" };
  }
  return { ok: true, id: trimmed };
}

function validateRole(role: unknown): { ok: true; role: CmsfnRole } | { ok: false; message: string; path?: string } {
  if (role == null || typeof role !== "object") {
    return { ok: false, message: "Role is required", path: "role" };
  }
  const r = role as Record<string, unknown>;
  const idResult = validateRoleId(String(r.id ?? ""));
  if (!idResult.ok) return { ok: false, message: idResult.message, path: "role.id" };
  const name = r.name;
  if (typeof name !== "string" || name.trim().length === 0) {
    return { ok: false, message: "Role name is required", path: "role.name" };
  }
  const rules = r.rules;
  if (!Array.isArray(rules)) {
    return { ok: false, message: "Role rules must be an array", path: "role.rules" };
  }
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule == null || typeof rule !== "object") {
      return { ok: false, message: "Invalid rule", path: `role.rules[${i}]` };
    }
    const rr = rule as Record<string, unknown>;
    if (rr.datasets !== "*" && !Array.isArray(rr.datasets)) {
      return { ok: false, message: "Rule datasets must be '*' or string[]", path: `role.rules[${i}].datasets` };
    }
    if (rr.types !== "*" && !Array.isArray(rr.types)) {
      return { ok: false, message: "Rule types must be '*' or string[]", path: `role.rules[${i}].types` };
    }
    if (rr.actions !== "*" && !Array.isArray(rr.actions)) {
      return { ok: false, message: "Rule actions must be '*' or string[]", path: `role.rules[${i}].actions` };
    }
  }
  const out: CmsfnRole = {
    id: idResult.id,
    name: (name as string).trim(),
    rules: rules as CmsfnRole["rules"],
  };
  return { ok: true, role: out };
}

/**
 * List all roles for a dataset. Returns all roles in deterministic order (by id).
 * Dataset is accepted for API compatibility; filtering by rule scope is not required in this phase.
 */
export async function rolesList(
  config: RolesStorageConfig,
  input: { dataset: string }
): Promise<CmsfnEnvelope<{ roles: CmsfnRole[] }>> {
  if (typeof input.dataset !== "string" || input.dataset.trim().length === 0) {
    return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  }
  const rows = await config.db.findMany({
    model: CMSFN_ROLES_TABLE,
    where: [],
    orderBy: [{ field: "id", direction: "asc" }],
  });
  const roles: CmsfnRole[] = (rows as Array<{ id: string; name: string; rules: unknown }>).map((row) => ({
    id: row.id,
    name: row.name,
    rules: Array.isArray(row.rules) ? (row.rules as CmsfnRole["rules"]) : [],
  }));
  return ok({ roles });
}

/**
 * Upsert a role by id.
 */
export async function rolesUpsert(
  config: RolesStorageConfig,
  input: { role: CmsfnRole }
): Promise<CmsfnEnvelope<{ role: CmsfnRole }>> {
  const v = validateRole(input.role);
  if (!v.ok) {
    return err("VALIDATION_FAILED", v.message, v.path ? { path: v.path } : {});
  }
  const { role } = v;
  const existing = await config.db.findOne({
    model: CMSFN_ROLES_TABLE,
    where: [{ field: "id", operator: "eq", value: role.id }],
  });
  const row = { id: role.id, name: role.name, rules: role.rules };
  if (existing) {
    await config.db.update({
      model: CMSFN_ROLES_TABLE,
      where: [{ field: "id", operator: "eq", value: role.id }],
      data: row,
    });
  } else {
    await config.db.create({
      model: CMSFN_ROLES_TABLE,
      data: row,
    });
  }
  return ok({ role });
}

/**
 * Delete a role by id.
 */
export async function rolesDelete(
  config: RolesStorageConfig,
  input: { roleId: string }
): Promise<CmsfnEnvelope<Record<string, never>>> {
  const v = validateRoleId(input.roleId);
  if (!v.ok) {
    return err("VALIDATION_FAILED", v.message, { path: "roleId" });
  }
  await config.db.delete({
    model: CMSFN_ROLES_TABLE,
    where: [{ field: "id", operator: "eq", value: v.id }],
  });
  return ok({});
}

/**
 * Load a single role by id (for auth evaluation).
 */
export async function roleById(
  config: RolesStorageConfig,
  roleId: string
): Promise<CmsfnRole | null> {
  const row = await config.db.findOne({
    model: CMSFN_ROLES_TABLE,
    where: [{ field: "id", operator: "eq", value: roleId }],
  });
  if (!row || typeof row !== "object") return null;
  const r = row as Record<string, unknown>;
  return {
    id: String(r.id),
    name: String(r.name),
    rules: Array.isArray(r.rules) ? (r.rules as CmsfnRole["rules"]) : [],
  };
}
