import type { JobSpec } from '../pipeline/types.js';
import { MemoryQueueAdapter as SharedMemoryQueueAdapter } from '@superfunctions/queue';

export interface JobPayload {
  runId: string;
  jobKey: string;
  jobSpec: JobSpec;
  pipelineRef?: { repo: string; ref: string; configPath?: string };
  env?: Record<string, string>;
  secretKeys?: string[];
}

export interface QueueClient {
  enqueue(queueName: string, payload: JobPayload): Promise<void>;
  dequeue(queueName: string): Promise<JobPayload | null>;
  dequeueMatching(queueName: string, matcher: (payload: JobPayload) => boolean): Promise<JobPayload | null>;
  peek(queueName: string): JobPayload[];
  size(queueName: string): number;
}

export class MemoryQueueClient extends SharedMemoryQueueAdapter<JobPayload> implements QueueClient {}

export const DEFAULT_QUEUE_NAME = 'cifn:jobs';
import {
  FlowFnQueueAdapter as SharedFlowFnQueueAdapter,
  MemoryQueueAdapter as SharedMemoryQueueAdapter,
} from '@superfunctions/queue';
import type { QueueAdapter } from './types.js';
import type { AdapterConfig } from './config.js';

export const MemoryQueueAdapter = SharedMemoryQueueAdapter as unknown as new () => QueueAdapter;
export const FlowFnQueueAdapter = SharedFlowFnQueueAdapter as unknown as new (config: {
  baseUrl: string;
  apiKey: string;
  fetch?: typeof globalThis.fetch;
}) => QueueAdapter;

export function createQueueAdapter(config: AdapterConfig['queue']): QueueAdapter {
  if (config.type === 'memory') {
    return new MemoryQueueAdapter();
  }

  if (!config.flowfnBaseUrl || !config.flowfnApiKey) {
    throw new Error('FlowFn adapter requires baseUrl and apiKey');
  }

  return new FlowFnQueueAdapter({
    baseUrl: config.flowfnBaseUrl,
    apiKey: config.flowfnApiKey,
  });
}
