import { describe, it, expect, beforeEach } from 'vitest';
import { signWebhookPayload } from '@superfunctions/webhooks';
import { verifySignature, handleWebhook, parseGitHubEvent } from './webhook.js';
import { CronScheduler } from './cron.js';
import { MemoryStore } from '../store/memory-store.js';
import { MemoryQueueClient, DEFAULT_QUEUE_NAME } from '../queue/flowfn-client.js';
import { MemorySecFnClient } from '../secrets/secfn-client.js';
import type { PipelineSpec } from '../pipeline/types.js';
import type { PipelineRef } from '../pipeline/resolver.js';

const SECRET = 'test-webhook-secret';
const API_KEY = 'test-key';

const validPipeline: PipelineSpec = {
  name: 'ci',
  on: { push: { branches: ['main'] } },
  jobs: {
    build: { 'runs-on': 'default', steps: [{ run: 'echo build' }] },
  },
};

/** Produces a pipeline doc string from a spec for use with pipelineRef resolver. */
function pipelineSpecToDoc(spec: PipelineSpec): string {
  return JSON.stringify(spec);
}

/** Resolver that returns the given spec as doc for any ref (for tests). */
function mockPipelineResolver(spec: PipelineSpec) {
  return async (_ref: PipelineRef) => ({
    doc: pipelineSpecToDoc(spec),
    resolvedConfigPath: '.ci/pipeline.yml',
  });
}

function sign(payload: string, secret: string): string {
  return signWebhookPayload(payload, secret, { algorithm: 'sha256', encoding: 'hex', prefix: 'sha256=' });
}

function makePayload(repo: string, ref: string): string {
  return JSON.stringify({
    repository: { clone_url: `https://github.com/${repo}.git`, full_name: repo },
    ref: `refs/heads/${ref}`,
  });
}

function authHeaders() {
  return { 'Content-Type': 'application/json', 'Authorization': `Bearer ${API_KEY}` };
}

describe('verifySignature', () => {
  it('returns true for valid signature', () => {
    const payload = '{"test": true}';
    const sig = sign(payload, SECRET);
    expect(verifySignature(payload, sig, SECRET)).toBe(true);
  });

  it('returns false for invalid signature', () => {
    const payload = '{"test": true}';
    expect(verifySignature(payload, 'sha256=invalid', SECRET)).toBe(false);
  });

  it('returns false for missing signature', () => {
    expect(verifySignature('body', '', SECRET)).toBe(false);
  });

  it('returns false for non-sha256 prefix', () => {
    expect(verifySignature('body', 'sha1=abc', SECRET)).toBe(false);
  });
});

describe('parseGitHubEvent', () => {
  it('maps push to push trigger type', () => {
    expect(parseGitHubEvent('push')).toBe('push');
  });

  it('maps pull_request to pull_request trigger type', () => {
    expect(parseGitHubEvent('pull_request')).toBe('pull_request');
  });

  it('returns null for unknown event', () => {
    expect(parseGitHubEvent('issues')).toBeNull();
  });
});

describe('handleWebhook', () => {
  if (eventType === 'push') return 'push';
  if (eventType === 'pull_request') return 'pull_request';
  return null;
}

export async function handleWebhook(
  rawBody: string,
  signature: string,
  eventType: string,
  options: WebhookOptions,
): Promise<WebhookResult> {
  if (!verifySignature(rawBody, signature, options.webhookSecret)) {
    return {
      status: 401,
      body: { ok: false, error: { code: 'BAD_REQUEST', message: 'Invalid webhook signature' } },
    };
  }

  const triggerType = parseGitHubEvent(eventType);
  if (!triggerType) {
    return {
      status: 400,
      body: { ok: false, error: { code: 'BAD_REQUEST', message: `Unsupported event type: ${eventType}` } },
    };
  }

  let payload: Record<string, unknown>;
  try {
    payload = JSON.parse(rawBody);
  } catch {
    return {
      status: 400,
      body: { ok: false, error: { code: 'BAD_REQUEST', message: 'Invalid JSON payload' } },
    };
  }

  const repository = payload.repository as { clone_url?: string; full_name?: string } | undefined;
  const ref = payload.ref as string | undefined;

  if (!repository || !ref) {
    return {
      status: 400,
      body: { ok: false, error: { code: 'BAD_REQUEST', message: 'Missing repository or ref in payload' } },
    };
  }

  const repo = repository.clone_url ?? repository.full_name ?? '';
  const refValue = ref.replace('refs/heads/', '');

  const pipelineRef: PipelineRef = { repo, ref: refValue };

  if (!options.pipelineResolver) {
    return {
      status: 422,
      body: { ok: false, error: { code: 'RUN_CREATE_FAILED', message: 'Pipeline resolver not configured' } },
    };
  }

  let doc: string;
  let resolvedConfigPath: string;
  try {
    const result = await options.pipelineResolver(pipelineRef);
    doc = result.doc;
    resolvedConfigPath = result.resolvedConfigPath;
  } catch (err) {
    const message = err instanceof ResolverError ? err.message : (err instanceof Error ? err.message : 'Pipeline resolution failed');
    return {
      status: 422,
      body: { ok: false, error: { code: 'RUN_CREATE_FAILED', message } },
    };
  }

  let parsed: unknown;
  try {
    parsed = parse(doc);
    await adapters.secrets.setSecret('CIFN_RUNNER_REGISTRATION_TOKEN', registrationToken);
  }

  const webhookSecret = process.env.CIFN_WEBHOOK_SECRET;

  const runtimeStore = await createRuntimeStore();
  const { app, dispatchPublisher } = createApp({ adapters, webhookSecret, store: runtimeStore.store });

  const server = createControlPlaneServer(app);
  let closing = false;
  const close = () => {
    if (closing) return;
    closing = true;
    server.close(async () => {
      try { await dispatchPublisher?.stop(); }
      catch { console.error('CiFn dispatch shutdown failed'); process.exitCode = 1; }
      try { await runtimeStore.close(); }
      catch { console.error('CiFn store shutdown failed'); process.exitCode = 1; }
    });
  };
  process.once('SIGTERM', close);
  process.once('SIGINT', close);
  server.once('error', () => {
    process.exitCode = 1;
    void runtimeStore.close().catch(() => console.error('CiFn store shutdown failed'));
  });

  server.listen(PORT, () => {
    dispatchPublisher?.start();
    const address = server.address();
    const listeningPort = address && typeof address === 'object' ? address.port : PORT;
    console.log(`CiFn Control Plane listening on port ${listeningPort}`);
    console.log(`Store: ${runtimeStore.mode}`);
    console.log(`Adapters: queue=${adapterConfig.queue.type}, artifacts=${adapterConfig.artifacts.type}, secrets=${adapterConfig.secrets.type}, logs=${adapterConfig.logs.type}`);
  });
}
start().catch((cause: unknown) => {
  console.error(`Fatal: ${cause instanceof Error ? cause.message : "Control-plane startup failed"}`);
  process.exitCode = 1;
});

