    upload(namespace: string, key: string, data: Buffer): Promise<string>;
    downloadByKey(namespace: string, key: string): Promise<Buffer | null>;
  };
  artifactStore?: {
    addArtifact(runId: string, artifact: { name: string; fileId: string; url?: string }): void;
  };
