export interface SendFnNotification {
  runId: string;
  status: 'success' | 'failure';
  pipelineRef: { repo: string; ref: string; configPath?: string };
  trigger: { type: string; payload?: Record<string, unknown> };
  createdAt: string;
  completedAt: string;
  summary: string;
}

export interface SendFnClient {
  sendNotification(notification: SendFnNotification): Promise<boolean>;
}

export interface SendFnConfig {
  enabled: boolean;
  webhookUrl?: string;
  emailTo?: string;
}

/**
 * Memory/mock SendFn client for testing
 */
export class MemorySendFnClient implements SendFnClient {
  public sentNotifications: SendFnNotification[] = [];

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    this.sentNotifications.push(notification);
    return true;
  }

  reset() {
    this.sentNotifications = [];
  }
}

/**
 * Webhook-based SendFn client
 */
export class WebhookSendFnClient implements SendFnClient {
  constructor(private webhookUrl: string) {}

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    try {
      const response = await fetch(this.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(notification),
      });
      return response.ok;
    } catch (err) {
      console.error('SendFn webhook notification failed:', err);
      return false;
    }
  }
}

/**
 * Email-based SendFn client (placeholder - would integrate with actual email service)
 */
export class EmailSendFnClient implements SendFnClient {
  constructor(private emailTo: string) {}

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    // In a real implementation, this would call an email service
    console.log(`[SendFn] Would send email to ${this.emailTo} for run ${notification.runId} (${notification.status})`);
    return true;
  }
}
  /** @deprecated Use adapters.logs instead */
  logClient?: { getLines(runId: string, jobKey: string): Array<{ line: string; timestamp: string; stepKey: string }> };
  webhookSecret?: string;
  /** Resolves pipelineRef to pipeline document string. Required for pipelineRef and webhook run creation. */
  pipelineResolver?: PipelineDocResolver;
  /** @deprecated Use adapters.secrets instead */
  secFn?: any;
  sendFn?: SendFnClient;
  sendFnConfig?: SendFnConfig;
  /** Integration adapters for queue, artifacts, secrets, and logs. Takes precedence over individual options. */
  adapters?: IntegrationAdapters;
}

export function createApp<TStore extends ControlPlaneStore = MemoryStore>(options: CreateAppOptions<TStore> = {}) {
  const app = new Hono();
  const runStore = (options.store ?? new MemoryStore()) as TStore;

  const queue = options.adapters?.queue ?? options.queue ?? new MemoryQueueClient();
  const artifactAdapter = options.adapters?.artifacts;
  const secFn = options.adapters?.secrets ?? options.secFn;
  const logs = options.adapters?.logs;
  const logClient = options.logClient;

  const sendFn = options.sendFn ?? new MemorySendFnClient();
  const sendFnConfig = options.sendFnConfig ?? { enabled: false };

  // Set up sendfn notification hook for run status changes
  runStore.setRunStatusChangeCallback((run) => {
    if (sendFnConfig.enabled && (run.status === 'success' || run.status === 'failure')) {
      const summary = `Run ${run.id} ${run.status}: ${Object.keys(run.jobs).length} job(s)`;
      sendFn.sendNotification({
        runId: run.id,
        status: run.status,
        pipelineRef: run.pipelineRef,
        trigger: run.trigger,
        createdAt: run.createdAt,
        completedAt: run.updatedAt,
        summary,
      }).catch(err => {
        console.error(`Failed to send notification for run ${run.id}:`, err);
      });
    }
  });

  const api = new Hono();

  // Apply Auth Middleware to all /api/v1 routes
  // Exclude /runners/register (uses token in body) and /runners/heartbeat (custom runner auth)
  // Health check is handled in middleware but we can also exclude it here if needed.
  api.use('/*', authMiddleware(secFn, ['/api/v1/runners/register', '/api/v1/runners/heartbeat', '/api/v1/runners/claims/']));

import type { Run, RunStatus, Job, JobStatus, Step, StepStatus } from '../pipeline/types.js';
import type { Artifact, Runner, CreateRunInput, ListRunsOptions, ListRunsResult } from './memory-store.js';

/** Memory implementations may be synchronous; durable implementations commit before resolving. */
export type StoreResult<T> = T | Promise<T>;
export interface ControlPlaneStore {
  createRun(input: CreateRunInput): StoreResult<Run>;
  getRun(runId: string): StoreResult<Run | undefined>;
  listRuns(options?: ListRunsOptions): StoreResult<ListRunsResult>;
  updateRunStatus(runId: string, status: RunStatus): StoreResult<Run | undefined>;
  setRunStatusChangeCallback(callback: (run: Run) => void): void;
  cancelRun(runId: string): StoreResult<{ run?: Run; error?: 'NOT_FOUND' | 'ALREADY_FINISHED' }>;
  updateJobStatus(runId: string, jobKey: string, status: JobStatus, startedAt?: string, completedAt?: string): StoreResult<Job | undefined>;
  updateStepStatus(runId: string, jobKey: string, stepKey: string, status: StepStatus, startedAt?: string, completedAt?: string): StoreResult<Step | undefined>;
  addArtifact(runId: string, artifact: Artifact): StoreResult<void>;
  getArtifacts(runId: string): StoreResult<Artifact[]>;
  createRunner(labels: string[], secretHash: string): StoreResult<Runner>;
  getRunner(runnerId: string): StoreResult<Runner | undefined>;
  updateRunnerLastSeen(runnerId: string): StoreResult<void>;
  registerJobSecretValues(runId: string, jobKey: string, secretValues: string[]): StoreResult<void>;
  getSecretValues(runId: string): StoreResult<string[]>;
}
