import { mkdir, rename, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { createProbefnError } from '@probefn/contracts/errors';
import type { JsonValue } from '@probefn/contracts/envelopes';

/** An identifier must remain one path segment after normalization. */
export function assertArtifactIdentifier(value: string, label = 'Artifact identifier'): void {
  if (typeof value !== 'string' || !/^[a-zA-Z0-9._-]+$/.test(value) || value === '.' || value === '..') {
    throw createProbefnError({ code: 'E_STORAGE_WRITE_FAILED',
      message: `${label} must be a non-reserved path segment.`, retryable: false });
  }
}

export function assertRepositoryRelativePath(relativePath: string): string {
  if (
    relativePath.length === 0 ||
    path.isAbsolute(relativePath) ||
    relativePath.startsWith('~')
  ) {
    throw createProbefnError({
      code: 'E_STORAGE_WRITE_FAILED',
      message: `Artifact path ${relativePath || '<empty>'} must be repository-relative.`,
      retryable: false,
      details: {
        path: relativePath,
      },
    });
  }

  const normalized = path.posix.normalize(relativePath.replaceAll(path.sep, path.posix.sep));

  if (normalized === '..' || normalized.startsWith('../')) {
    throw createProbefnError({
      code: 'E_STORAGE_WRITE_FAILED',
      message: `Artifact path ${relativePath} escapes the repository root.`,
      retryable: false,
      details: {
        path: relativePath,
      },
    });
  }

  return normalized;
}

export async function writeJsonManifestAtomic(
  repoRoot: string,
  relativePath: string,
  value: JsonValue | Record<string, unknown> | unknown[] | object,
): Promise<number> {
  return writeAtomicFile(
    repoRoot,
    relativePath,
    `${JSON.stringify(value, null, 2)}\n`,
  );
}

export async function writeAtomicFile(
  repoRoot: string,
  relativePath: string,
  contents: string | Uint8Array,
): Promise<number> {
  const normalizedPath = assertRepositoryRelativePath(relativePath);
  const absolutePath = path.resolve(repoRoot, normalizedPath);
  const directory = path.dirname(absolutePath);
  const tempPath = `${absolutePath}.tmp-${process.pid}-${Date.now()}`;

  try {
    await mkdir(directory, { recursive: true });
    await writeFile(tempPath, contents);
    await rename(tempPath, absolutePath);
    const fileStats = await stat(absolutePath);
    return fileStats.size;
  } catch (error) {
    throw createProbefnError({
      code: 'E_STORAGE_WRITE_FAILED',
      message: `Could not write artifact ${normalizedPath}.`,
      retryable: false,
      details: {
        path: normalizedPath,
      },
      cause: error,
    });
  }
}
import path from 'node:path';

import { createProbefnError } from '@probefn/contracts/errors';
import type { CheckpointManifest, RunManifest } from '@probefn/contracts/manifests';
import { ArtifactCapTracker, DEFAULT_STORAGE_CAPS, type StorageCaps } from './caps.js';
import { NdjsonEventSink, type EventSinkOptions } from './event-sink.js';
import { assertArtifactIdentifier, assertRepositoryRelativePath, writeAtomicFile } from './manifest-writer.js';
import { redactSensitiveData } from './redaction.js';

export interface ArtifactStoreOptions {
  repoRoot: string;
  artifactRoot?: string;
  caps?: Partial<StorageCaps>;
}

export interface RunPaths {
  runRoot: string;
  checkpointRoot: string;
  diffRoot: string;
  devServerRoot: string;
  eventRoot: string;
  sessionManifestPath: string;
  tracePath: string;
  reportJsonPath: string;
  reportMarkdownPath: string;
}

export interface CheckpointPaths {
  root: string;
  manifestPath: string;
  screenshotPath: string;
  domPath: string;
  axPath: string;
  layoutPath: string;
  stylesPath: string;
  videoPath: string;
}

export class ArtifactStore {
  private readonly repoRoot: string;
  private readonly artifactRoot: string;
  private readonly capTracker: ArtifactCapTracker;
  private writeQueue: Promise<void> = Promise.resolve();

  public constructor(options: ArtifactStoreOptions) {
    this.repoRoot = options.repoRoot;
    this.artifactRoot = assertRepositoryRelativePath(options.artifactRoot ?? '.artifacts');
    this.capTracker = new ArtifactCapTracker(
      options.caps?.maxArtifactBytes ?? DEFAULT_STORAGE_CAPS.maxArtifactBytes,
    );
  }

  public getArtifactRoot(): string {
    return this.artifactRoot;
  }

  public getRunPaths(runId: string): RunPaths {
    assertRunId(runId);

    const runRoot = path.posix.join(this.artifactRoot, 'runs', runId);
    return {
      runRoot,
      checkpointRoot: path.posix.join(runRoot, 'checkpoints'),
      diffRoot: path.posix.join(runRoot, 'diffs'),
      devServerRoot: path.posix.join(runRoot, 'devserver'),
      eventRoot: path.posix.join(runRoot, 'events'),
      sessionManifestPath: path.posix.join(runRoot, 'session.json'),
      tracePath: path.posix.join(runRoot, 'browser.trace.zip'),
      reportJsonPath: path.posix.join(runRoot, 'report.json'),
      reportMarkdownPath: path.posix.join(runRoot, 'report.md'),
    };
  }

  public getCheckpointPaths(runId: string, checkpointName: string): CheckpointPaths {
    const runPaths = this.getRunPaths(runId);
    const safeCheckpointName = sanitizeSegment(checkpointName);
    const root = path.posix.join(runPaths.checkpointRoot, safeCheckpointName);

    return {
      root,
      manifestPath: path.posix.join(root, 'checkpoint.json'),
      screenshotPath: path.posix.join(root, 'screenshot.png'),
      domPath: path.posix.join(root, 'dom.json'),
      axPath: path.posix.join(root, 'ax.json'),
      layoutPath: path.posix.join(root, 'layout.json'),
      stylesPath: path.posix.join(root, 'styles.json'),
      videoPath: path.posix.join(root, 'video.webm'),
    };
  }

  public async writeRunManifest(runId: string, manifest: RunManifest): Promise<string> {
    const relativePath = this.getRunPaths(runId).sessionManifestPath;
    await this.writeJson(relativePath, manifest);
    return relativePath;
  }

  public async writeCheckpointManifest(
    runId: string,
    checkpointName: string,
    manifest: CheckpointManifest,
  ): Promise<string> {
    const relativePath = this.getCheckpointPaths(runId, checkpointName).manifestPath;
    await this.writeJson(relativePath, manifest);
    return relativePath;
  }

  public async writeReport(
    runId: string,
    format: 'json' | 'markdown',
    contents: string | Record<string, unknown>,
  ): Promise<string> {
    const runPaths = this.getRunPaths(runId);
    const relativePath = format === 'json' ? runPaths.reportJsonPath : runPaths.reportMarkdownPath;
    if (format === 'json') {
      await this.writeJson(
        relativePath,
        redactSensitiveData(contents as Record<string, unknown>).value,
      );
    } else {
      await this.writeText(relativePath, redactSensitiveData(contents as string).value);
    }
    return relativePath;
  }

  public async writeArtifact(relativePath: string, contents: string | Uint8Array): Promise<string> {
    await this.writeText(relativePath, contents);
    return assertRepositoryRelativePath(relativePath);
  }

  public createEventSink(
    runId: string,
    baseName: string,
    directory: 'devserver' | 'events' | `checkpoints/${string}`,
    options?: Partial<
      Omit<EventSinkOptions, 'repoRoot' | 'relativeDirectory' | 'baseName' | 'capTracker'>
    >,
  ): NdjsonEventSink {
    const runPaths = this.getRunPaths(runId);
    const relativeDirectory =
      directory === 'devserver'
        ? runPaths.devServerRoot
        : directory === 'events'
          ? runPaths.eventRoot
        : path.posix.join(runPaths.runRoot, directory);

    return new NdjsonEventSink({
      repoRoot: this.repoRoot,
      relativeDirectory,
      baseName,
      capTracker: this.capTracker,
      ...(options?.policy ? { policy: options.policy } : {}),
    });
  }

  private async writeJson(relativePath: string, value: object): Promise<void> {
    // Serialize once so the reserved byte count and persisted bytes are identical.
    await this.writeText(relativePath, `${JSON.stringify(value, null, 2)}\n`);
  }

  private async writeText(relativePath: string, contents: string | Uint8Array): Promise<void> {
    const normalizedPath = assertRepositoryRelativePath(relativePath);
    const snapshot = typeof contents === 'string' ? contents : new Uint8Array(contents);
    const bytes = typeof snapshot === 'string' ? Buffer.byteLength(snapshot) : snapshot.byteLength;
    const reservation = this.capTracker.reserve(bytes, normalizedPath);
    // Also serialize replacements: atomic writer temp names are time based, and two
    // simultaneous writes to one destination must not share a temporary file.
    const operation = this.writeQueue.then(async () => {
      try { await writeAtomicFile(this.repoRoot, normalizedPath, snapshot); }
      finally {
        // A failed atomic writer may have created a partial temporary file or renamed
        // before failing its stat. Conservatively charge the attempt, including overwrites.
        reservation.commit();
      }
    });
    this.writeQueue = operation.then(() => undefined, () => undefined);
    await operation;
  }
}

function sanitizeSegment(value: string): string {
  const sanitized = value
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

  if (sanitized.length === 0) {
    throw createProbefnError({
      code: 'E_STORAGE_WRITE_FAILED',
      message: 'Checkpoint names must contain at least one safe character.',
      retryable: false,
      details: {
        value,
      },
    });
  }

  assertArtifactIdentifier(sanitized, 'Checkpoint name');
  return sanitized;
}

function assertRunId(runId: string): void {
  assertArtifactIdentifier(runId, 'Run id');
}
import { access, copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { createProbefnError } from '@probefn/contracts/errors';
import { ArtifactStore, assertArtifactIdentifier, assertRepositoryRelativePath } from '@probefn/storage';

export interface PlaywrightStorageState {
  cookies: unknown[];
  origins: unknown[];
}

export interface AuthProfileStoreOptions {
  repoRoot: string;
  artifactStore: ArtifactStore;
}

export interface SavedAuthProfile {
  profileId: string;
  storageStatePath: string;
}

export interface LoadedAuthProfile extends SavedAuthProfile {
  storageState: PlaywrightStorageState;
}

export class AuthProfileStore {
  private readonly repoRoot: string;
  private readonly artifactStore: ArtifactStore;

  public constructor(options: AuthProfileStoreOptions) {
    this.repoRoot = options.repoRoot;
    this.artifactStore = options.artifactStore;
  }

  public getProfileStorageStatePath(profileId: string): string {
    return path.posix.join(
      this.artifactStore.getArtifactRoot(),
      'auth-profiles',
      sanitizeSegment(profileId),
      'storage-state.json',
    );
  }

  public getSessionStorageStatePath(runId: string): string {
    return path.posix.join(
      this.artifactStore.getRunPaths(runId).runRoot,
      'session-storage',
      'storage-state.json',
    );
  }

  public async saveProfile(
    input: {
      profileId: string;
      storageState: PlaywrightStorageState;
    },
  ): Promise<SavedAuthProfile> {
    const storageStatePath = this.getProfileStorageStatePath(input.profileId);
    await this.writeJson(storageStatePath, input.storageState);
    return {
      profileId: input.profileId,
      storageStatePath,
    };
  }

  public async saveProfileFromPath(
    input: {
      profileId: string;
      sourceStorageStatePath: string;
    },
  ): Promise<SavedAuthProfile> {
    await this.assertExists(input.sourceStorageStatePath, 'sourceStorageStatePath');
    const storageStatePath = this.getProfileStorageStatePath(input.profileId);
    await this.copyRepoRelativeFile(input.sourceStorageStatePath, storageStatePath);
    return {
      profileId: input.profileId,
      storageStatePath,
    };
  }

  public async loadProfile(profileId: string): Promise<LoadedAuthProfile> {
    const storageStatePath = this.getProfileStorageStatePath(profileId);
    try {
      const storageState = JSON.parse(
        await readFile(path.resolve(this.repoRoot, storageStatePath), 'utf8'),
      ) as PlaywrightStorageState;
      return {
        profileId,
        storageStatePath,
        storageState,
      };
    } catch (error) {
      if (isMissing(error)) {
        throw createProbefnError({
          code: 'E_AUTH_PROFILE_NOT_FOUND',
          message: `Auth profile ${profileId} was not found.`,
          retryable: false,
          details: {
            authProfileId: profileId,
          },
        });
      }

      throw error;
    }
  }

  public async initializeSessionStorageFromProfile(
    input: {
      profileId: string;
      runId: string;
    },
  ): Promise<SavedAuthProfile> {
    const loaded = await this.loadProfile(input.profileId);
    const storageStatePath = this.getSessionStorageStatePath(input.runId);
    await this.copyRepoRelativeFile(loaded.storageStatePath, storageStatePath);
    return {
      profileId: input.profileId,
      storageStatePath,
    };
  }

  public async writeSessionStorageState(
    input: {
      runId: string;
      storageState: PlaywrightStorageState;
    },
  ): Promise<string> {
    const storageStatePath = this.getSessionStorageStatePath(input.runId);
    await this.writeJson(storageStatePath, input.storageState);
    return storageStatePath;
  }

  public async hasStorageStatePath(storageStatePath: string | undefined): Promise<boolean> {
    if (!storageStatePath) {
      return false;
    }

    try {
      await this.assertExists(storageStatePath, 'storageStatePath');
      return true;
    } catch (error) {
      const probefnError =
        error &&
        typeof error === 'object' &&
        'code' in error
          ? (error as { code?: string })
          : null;
      if (probefnError?.code === 'E_STORAGE_WRITE_FAILED') {
        return false;
      }

      throw error;
    }
  }

  private async writeJson(relativePath: string, value: PlaywrightStorageState): Promise<void> {
    const absolutePath = path.resolve(this.repoRoot, relativePath);
    await mkdir(path.dirname(absolutePath), {
      recursive: true,
    });
    await writeFile(absolutePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
  }

  private async copyRepoRelativeFile(sourceRelativePath: string, targetRelativePath: string): Promise<void> {
    assertRepositoryRelativePath(sourceRelativePath);
    assertRepositoryRelativePath(targetRelativePath);
    const targetPath = path.resolve(this.repoRoot, targetRelativePath);
    await mkdir(path.dirname(targetPath), {
      recursive: true,
    });
    await copyFile(
      path.resolve(this.repoRoot, sourceRelativePath),
      targetPath,
    );
  }

  private async assertExists(relativePath: string, pathLabel: string): Promise<void> {
    assertRepositoryRelativePath(relativePath);
    try {
      await access(path.resolve(this.repoRoot, relativePath));
    } catch (error) {
      throw createProbefnError({
        code: 'E_STORAGE_WRITE_FAILED',
        message: `${pathLabel} does not exist.`,
        retryable: false,
        details: {
          path: relativePath,
        },
        cause: error,
      });
    }
  }
}

function sanitizeSegment(value: string): string {
  const sanitized = value
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

  if (sanitized.length === 0) {
    throw createProbefnError({
      code: 'E_CONFIG_INVALID',
      message: 'Auth profile identifiers must contain at least one safe character.',
      retryable: false,
    });
  }

  assertArtifactIdentifier(sanitized, 'Auth profile id');
  return sanitized;
}

function isMissing(error: unknown): boolean {
  return Boolean(
    error &&
      typeof error === 'object' &&
      'code' in error &&
      (error as { code?: string }).code === 'ENOENT',
  );
}
import { readFile } from 'node:fs/promises';
import path from 'node:path';

import type { BrowserEngine, DeterministicSettings, SessionMode } from '@probefn/contracts/config';
import { createProbefnError } from '@probefn/contracts/errors';
import type { ReportJsonDocument } from '@probefn/session-reporter';
import { ArtifactStore, assertArtifactIdentifier } from '@probefn/storage';

import { ReportService } from './report-service.js';
import { createSessionState, type SessionArtifactsState, type SessionLifecycleStatus, type SessionState } from './session-state.js';

export interface SessionManagerOptions {
  repoRoot: string;
  artifactStore: ArtifactStore;
  now?: () => string;
}

export interface InitializeSessionStateInput {
  sessionId: string;
  runId: string;
  mode: SessionMode;
  browser: BrowserEngine;
  deterministic: DeterministicSettings;
  artifactRoot: string;
  startedAt: string;
  manifestPath: string;
  resolvedUrl?: string;
  artifacts?: Partial<SessionArtifactsState>;
}

export interface ExportReportResult {
  reportPath: string;
  tracePath: string | null;
  redactedValueCount: number;
  warnings: string[];
  includes: string[];
  reportData: ReportJsonDocument;
}

export class SessionManager {
  private readonly repoRoot: string;
  private readonly artifactStore: ArtifactStore;
  private readonly now: () => string;

  public constructor(options: SessionManagerOptions) {
    this.repoRoot = options.repoRoot;
    this.artifactStore = options.artifactStore;
    this.now = options.now ?? (() => new Date().toISOString());
  }

  public async initialize(input: InitializeSessionStateInput): Promise<SessionState> {
    assertArtifactIdentifier(input.runId, 'Run id');
    assertArtifactIdentifier(input.sessionId, 'Session id');
    const state = createSessionState({
      sessionId: input.sessionId,
      runId: input.runId,
      mode: input.mode,
      browser: input.browser,
      deterministic: input.deterministic,
      artifactRoot: input.artifactRoot,
      startedAt: input.startedAt,
      status: 'starting',
      ...(input.resolvedUrl ? { resolvedUrl: input.resolvedUrl } : {}),
      artifacts: {
        manifestPath: input.manifestPath,
        ...(input.artifacts?.tracePath !== undefined ? { tracePath: input.artifacts.tracePath } : {}),
        ...(input.artifacts?.storageStatePath ? { storageStatePath: input.artifacts.storageStatePath } : {}),
        ...(input.artifacts?.reportJsonPath ? { reportJsonPath: input.artifacts.reportJsonPath } : {}),
        ...(input.artifacts?.reportMarkdownPath ? { reportMarkdownPath: input.artifacts.reportMarkdownPath } : {}),
        ...(input.artifacts?.consoleSinkPath ? { consoleSinkPath: input.artifacts.consoleSinkPath } : {}),
        ...(input.artifacts?.pageErrorSinkPath ? { pageErrorSinkPath: input.artifacts.pageErrorSinkPath } : {}),
        ...(input.artifacts?.networkSinkPath ? { networkSinkPath: input.artifacts.networkSinkPath } : {}),
        ...(input.artifacts?.devServerStdoutSinkPath ? { devServerStdoutSinkPath: input.artifacts.devServerStdoutSinkPath } : {}),
        ...(input.artifacts?.devServerStderrSinkPath ? { devServerStderrSinkPath: input.artifacts.devServerStderrSinkPath } : {}),
      },
    });
    await this.writeState(state);
    return state;
  }

  public async read(sessionId: string): Promise<SessionState> {
    const relativePath = this.getStatePath(sessionId);
    const absolutePath = path.resolve(this.repoRoot, relativePath);

    try {
      const contents = await readFile(absolutePath, 'utf8');
      return JSON.parse(contents) as SessionState;
    } catch (error) {
      throw createProbefnError({
        code: 'E_SESSION_NOT_FOUND',
        message: `Session ${sessionId} was not found.`,
        retryable: false,
        details: {
          sessionId,
        },
        cause: error,
      });
    }
  }

  public async markRunning(
    sessionId: string,
    patch: {
      endedAt?: string;
      resolvedUrl?: string;
      artifacts?: Partial<SessionArtifactsState>;
    } = {},
  ): Promise<SessionState> {
    return this.update(sessionId, (currentState) =>
      this.withPatch(currentState, 'running', patch),
    );
  }

  public async markCompleted(
    sessionId: string,
    patch: {
      endedAt?: string;
      resolvedUrl?: string;
      artifacts?: Partial<SessionArtifactsState>;
    } = {},
  ): Promise<SessionState> {
    return this.update(sessionId, (currentState) =>
      this.withPatch(currentState, 'completed', {
        ...patch,
        endedAt: patch.endedAt ?? this.now(),
      }),
    );
  }

  public async markFailed(
    sessionId: string,
    patch: {
      endedAt?: string;
      resolvedUrl?: string;
      artifacts?: Partial<SessionArtifactsState>;
    } = {},
  ): Promise<SessionState> {
    return this.update(sessionId, (currentState) =>
      this.withPatch(currentState, 'failed', {
        ...patch,
        endedAt: patch.endedAt ?? this.now(),
      }),
    );
  }

  public async exportReport(
    input: {
      sessionId: string;
      format: 'json' | 'markdown';
    },
  ): Promise<ExportReportResult> {
    const state = await this.read(input.sessionId);
    const reportService = new ReportService({
      repoRoot: this.repoRoot,
      artifactStore: this.artifactStore,
    });
    const exportedReport = await reportService.exportReport({
      session: state,
      format: input.format,
    });

    const nextState = this.withPatch(state, state.status, {
      artifacts: {
        ...(input.format === 'json' ? { reportJsonPath: exportedReport.reportPath } : {}),
        ...(input.format === 'markdown' ? { reportMarkdownPath: exportedReport.reportPath } : {}),
      },
    });
    await this.writeState(nextState);

    return {
      ...exportedReport,
    };
  }

  public getStatePath(sessionId: string): string {
    assertArtifactIdentifier(sessionId, 'Session id');
    return path.posix.join(this.artifactStore.getArtifactRoot(), 'session-state', `${sessionId}.json`);
  }

  private async update(
    sessionId: string,
    updater: (currentState: SessionState) => SessionState,
  ): Promise<SessionState> {
    const currentState = await this.read(sessionId);
    const nextState = updater(currentState);
    await this.writeState(nextState);
    return nextState;
  }

  private withPatch(
    currentState: SessionState,
    status: SessionLifecycleStatus,
    patch: {
      endedAt?: string;
      resolvedUrl?: string;
      artifacts?: Partial<SessionArtifactsState>;
    },
  ): SessionState {
    return createSessionState({
      sessionId: currentState.sessionId,
      runId: currentState.runId,
