### 7.3 Optional Notifications (SendFn)

CiFn supports optional notifications on run completion (success or failure) via **sendfn** integration:

**Configuration:**
- Per-pipeline or global configuration flag: `notifyOnRunComplete: true`
- Webhook URL or email address for notifications
- When not configured: no notification sent (opt-in feature)

**Notification payload:**
- `runId`, `status` (success/failure), `pipelineRef`, `trigger`, `createdAt`, `completedAt`, `summary`
- Sent as HTTP POST to configured webhook or via email service

import type { DatabaseStore } from '../store/database-store.js';
import type { ControlPlaneStore } from '../store/store.js';
import type { SendFnNotification } from './sendfn-client.js';

export interface NotificationIntent {
  id: string;
  destination: string;
  payload: SendFnNotification & { eventId: string };
  attempts: number;
  nextAttemptAt: number;
  lease?: { token: string; expiresAt: number };
  deliveredAt?: string;
}
export type NotificationStore = Pick<DatabaseStore, 'configureNotifications' | 'listNotificationRuns' | 'claimNotification' | 'finishNotification'>;
export function isNotificationStore(store: ControlPlaneStore): store is ControlPlaneStore & NotificationStore {
  const value = store as Partial<NotificationStore>;
  return ['configureNotifications', 'listNotificationRuns', 'claimNotification', 'finishNotification']
    .every(key => typeof value[key as keyof NotificationStore] === 'function');
}
export const NOTIFICATION_TIMEOUT_MS = 3_000;
export const NOTIFICATION_LEASE_MS = 10_000;
export const notificationBackoff = (attempts: number) => Math.min(60_000, 1_000 * 2 ** Math.min(Math.max(attempts - 1, 0), 6));

/** At-least-once HTTP delivery. Receiver deduplication uses the stable event ID. */
export class NotificationPublisher {
  private cursor?: string;
  private active?: Promise<void>;
  private timer?: ReturnType<typeof setInterval>;
  constructor(private store: NotificationStore) {}
  tick(): Promise<void> {
    if (this.active) return this.active;
    this.active = (async () => {
      const page = await this.store.listNotificationRuns(this.cursor);
      for (const runId of page.runIds) {
        const intent = await this.store.claimNotification(runId, Date.now(), NOTIFICATION_LEASE_MS);
        if (!intent?.lease) continue;
        let delivered = false;
        try {
          const response = await fetch(intent.destination, {
            method: 'POST', headers: { 'Content-Type': 'application/json', 'Idempotency-Key': intent.id, 'X-CiFn-Event-Id': intent.id },
            body: JSON.stringify(intent.payload), signal: AbortSignal.timeout(NOTIFICATION_TIMEOUT_MS), redirect: 'error',
          });
          delivered = response.ok;
          await response.body?.cancel();
        } catch { /* Never include destination credentials or payload in diagnostics. */ }
        await this.store.finishNotification(runId, intent.id, intent.lease.token, delivered, Date.now());
      }
      this.cursor = page.nextCursor;
    })().finally(() => { this.active = undefined; });
    return this.active;
  }
  start(): void {
    if (this.timer) return;
    const tick = () => { void this.tick().catch(() => console.error('CiFn notification delivery pending retry')); };
    this.timer = setInterval(tick, 1_000); this.timer.unref(); tick();
  }
  async stop(): Promise<void> { if (this.timer) clearInterval(this.timer); this.timer = undefined; await this.active; }
}
export interface SendFnNotification {
  runId: string;
  status: 'success' | 'failure' | 'cancelled';
  pipelineRef: { repo: string; ref: string; configPath?: string };
  trigger: { type: string; payload?: Record<string, unknown> };
  createdAt: string;
  completedAt: string;
  summary: string;
}

export interface SendFnClient {
  sendNotification(notification: SendFnNotification): Promise<boolean>;
}

export interface SendFnConfig {
  enabled: boolean;
  webhookUrl?: string;
  emailTo?: string;
}

/**
 * Memory/mock SendFn client for testing
 */
export class MemorySendFnClient implements SendFnClient {
  public sentNotifications: SendFnNotification[] = [];

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    this.sentNotifications.push(notification);
    return true;
  }

  reset() {
    this.sentNotifications = [];
  }
}

/**
 * Webhook-based SendFn client
 */
export class WebhookSendFnClient implements SendFnClient {
  constructor(private webhookUrl: string) {}

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    try {
      const response = await fetch(this.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(notification),
        signal: AbortSignal.timeout(3_000), redirect: 'error',
      });
      const delivered = response.ok;
      await response.body?.cancel();
      return delivered;
    } catch (err) {
      console.error('CiFn webhook notification delivery failed');
      return false;
    }
  }
}

/**
 * Email-based SendFn client (placeholder - would integrate with actual email service)
 */
export class EmailSendFnClient implements SendFnClient {
  constructor(private emailTo: string) {}

  async sendNotification(notification: SendFnNotification): Promise<boolean> {
    throw new Error('CiFn email notification delivery is not configured; supply a real SendFn integration');
  }
}


export function notificationDestination(config: SendFnConfig): string | undefined {
  if (typeof config.enabled !== 'boolean') throw new Error('CiFn notification enabled must be a boolean');
  if (!config.enabled) return undefined;
  if (config.emailTo) throw new Error('CiFn durable email notifications require a real SendFn integration');
  if (!config.webhookUrl) throw new Error('Enabled CiFn notifications require an explicit webhook URL');
  let url: URL;
  try { url = new URL(config.webhookUrl); } catch { throw new Error('Invalid CiFn notification webhook URL'); }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) throw new Error('CiFn notification webhook must use HTTP(S) without userinfo or fragment');
  return url.toString();
}
export function parseNotificationConfig(env: Record<string, string | undefined>): SendFnConfig {
  const flag = env.CIFN_NOTIFY_ON_RUN_COMPLETE;
  if (flag !== undefined && flag !== 'true' && flag !== 'false') throw new Error('CIFN_NOTIFY_ON_RUN_COMPLETE must be true or false');
  const config = { enabled: flag === 'true', webhookUrl: env.CIFN_NOTIFICATION_WEBHOOK_URL, emailTo: env.CIFN_NOTIFICATION_EMAIL_TO };
  notificationDestination(config);
  return config;
}
