                    bucket = get_bucket(flag.key, user.id)
                    # Bucket is 0-99. 
                    # If rollout is 10%, we want buckets 0-9. 
                    # So if bucket >= rollout, we skip.
                    if bucket >= rule.rollout_percentage:
                        continue

            # 3. Return Variation
            if rule.variation_id:
