    assert client.get_flag('feature') == 'control'
    client.identify('paid-user', {'plan': 'pro'})
    assert client.get_flag('feature') == 'treatment'
    client.reset()
    assert client.get_flag('feature') == 'control'
    client.set_flags([])
    assert client.get_flag('feature', 'removed') == 'removed'

