  }

  reset() {
    this.identity.reset();
  }

  getFlag(key: string, defaultValue: FlagValue = false): FlagValue {
    const user = this.identity.getUser();
    return this.flags.getFlag(key, defaultValue, user);
  }

  track(event: string, properties?: EventProperties) {
